mapper.select:
SELECT 
  FROM (
        SELECT *
             , f_get_empTrans(rpt02_person_id, (rpt02_yyyymm||'.01')::date, 'org_code_nm') AS rpt02_org_nm
             , (SELECT COUNT(*) FROM sys10_file WHERE sys10_parent_id = rpt02_month_id)    AS rpt02_file_count
          FROM rpt02_month
         WHERE rpt02_month_id   = #{monthId}
           AND rpt02_company_id = #{companyId}
       ) t

mapper.update:
UPDATE rpt02_month
   SET rpt02_yyyymm  = #{req.yyyyMm}
     , rpt02_content = #{req.content}
     , rpt02_note    = #{req.note}
 WHERE rpt02_month_id   = #{req.monthId}
   AND rpt02_company_id = #{companyId}
   AND rpt02_person_id  = #{personId}

mapper.delete:
DELETE FROM rpt02_month
 WHERE rpt02_month_id   = #{monthId}
   AND rpt02_company_id = #{companyId}
   AND rpt02_person_id  = #{personId}

DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}
